\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tabularx}
\pagestyle{empty}

% ══ Dark-Mode Developer Palette ══
\definecolor{primary}{HTML}{3B82F6}      % Electric blue
\definecolor{secondary}{HTML}{F59E0B}    % Amber
\definecolor{accent}{HTML}{10B981}       % Mint green
\definecolor{bgposter}{HTML}{0F172A}     % Deep navy background
\definecolor{cardbg}{HTML}{1E293B}       % Dark slate cards
\definecolor{cardbgalt}{HTML}{162032}    % Slightly darker variant
\definecolor{bordercol}{HTML}{334155}    % Subtle borders
\definecolor{textmain}{HTML}{F1F5F9}     % Near-white text
\definecolor{textmuted}{HTML}{94A3B8}    % Muted text
\definecolor{stathighlight}{HTML}{172554} % Deep blue stat bg
\definecolor{redaccent}{HTML}{EF4444}    % Red accent
\definecolor{purpleaccent}{HTML}{8B5CF6} % Purple accent
\definecolor{orangeaccent}{HTML}{F97316} % Orange accent
\definecolor{cyanaccent}{HTML}{06B6D4}   % Cyan accent

\pagecolor{bgposter}
\color{textmain}

% ══ List styling ══
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ══ Figure+caption macro ══
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{20}{26}\selectfont\color{textmuted}\textit{#3}}\vspace{1mm}%
}

% ══ Card styles for dark mode ══
\tcbset{
  bluecard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardbgalt,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.25, offset={2pt}{-2pt}},
  },
  ambercard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardbgalt,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.25, offset={2pt}{-2pt}},
  },
  mintcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbgalt,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.25, offset={2pt}{-2pt}},
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=primary!20!bgposter,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{textmain},
    coltitle=textmain, colbacktitle=primary!60!bgposter,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.3, offset={2pt}{-2pt}},
  },
  statcard/.style={
    enhanced, arc=4pt, boxrule=1pt, colframe=primary!40,
    colback=stathighlight,
    left=10pt, right=10pt, top=8pt, bottom=8pt,
    valign=center, halign=center,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=2mm},
]

% ════════════════════════════════════════════════
% TITLE BAR
% ════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!90!bgposter, colframe=primary!90!bgposter,
  colupper=textmain, arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35, offset={3pt}{-3pt}}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{68}{82}\selectfont\bfseries State of Developer Ecosystem 2024}\\[10pt]
  {\fontsize{30}{38}\selectfont Language Wars \& Rising Stars}\\[8pt]
  {\fontsize{22}{28}\selectfont\color{textmain!65} Based on 23,262 developers worldwide \quad$\bullet$\quad JetBrains Survey 2024}
}

% ════════════════════════════════════════════════
% STAT BANNER
% ════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!40},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{primary} 61\%}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} JavaScript Usage}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!50}{accent!15!bgposter}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{accent} 57\%}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} Python Rising}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!50}{secondary!15!bgposter}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{secondary} 12$\to$37\%}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} TypeScript Surge}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{purpleaccent!50}{purpleaccent!15!bgposter}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{purpleaccent} 199}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textmuted} TS Promise Index}\vspace{5pt}%
    }}
  \end{minipage}
}

% ════════════════════════════════════════════════
% LANGUAGE TRAJECTORY — CENTERPIECE (full width)
% ════════════════════════════════════════════════
\posterbox[
  bluecard, title={Top Programming Languages (2017--2024)}
]{name=langtrajectory, column=1, span=2, between=row5 and row11}{
  \posterfig{0.96}{figures/language_trajectory.png}{Eight-year usage trajectory: JavaScript plateaus at 61\% while Python climbs to 57\% --- the gap narrows to just 4 points. TypeScript surges from 12\% to 37\%.}

  \vspace{-2mm}
  \centering
  \colorbox{primary!25!bgposter}{\parbox{0.92\linewidth}{%
    \centering\fontsize{22}{28}\selectfont\color{textmain}%
    \textbf{The hierarchy is reshaping:} Python is closing in on JavaScript, and TypeScript is the breakout story of the decade.%
  }}
}

% ════════════════════════════════════════════════
% PROMISE INDEX (left column)
% ════════════════════════════════════════════════
\posterbox[
  ambercard, title={Rising Stars: Promise Index}
]{name=promise, column=1, between=row11 and row15}{
  \posterfig{0.95}{figures/promise_index.png}{JetBrains Language Promise Index: combines 5-year growth, stability, adoption intent, and retention.}

  \vspace{-1mm}
  \fontsize{22}{30}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item \textbf{\color{primary}TypeScript (199)} --- top-ranked outlook
    \item \textbf{\color{orangeaccent}Rust (198)} --- near-perfect score
    \item Go \& Rust: most \emph{planned} adoptions
    \item 1 in 6 Go users considering Rust switch
  \end{itemize}
}

% ════════════════════════════════════════════════
% DATABASE TRENDS (right column)
% ════════════════════════════════════════════════
\posterbox[
  mintcard, title={Databases: PostgreSQL's Surge}
]{name=databases, column=2, between=row11 and row15}{
  \posterfig{0.95}{figures/database_trends.png}{PostgreSQL climbs from 32\% to 45\% while MySQL holds at 52\%.}

  \vspace{-1mm}
  \fontsize{22}{30}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item PostgreSQL: \textbf{\color{accent}+13pp} since 2019
    \item Open-source DBs dominate the stack
    \item MySQL still leads but gap narrowing
    \item MongoDB \& SQLite stable at 30\%
  \end{itemize}
}

% ════════════════════════════════════════════════
% CLOUD & PLATFORMS (left column)
% ════════════════════════════════════════════════
\posterbox[
  ambercard, title={Cloud \& Platforms: Where Code Runs}
]{name=cloud, column=1, between=row15 and row18}{
  \posterfig{0.95}{figures/cloud_platforms.png}{AWS leads at 46\% but dips from 51\%. Desktop (53\%) still surpasses mobile (30\%).}

  \fontsize{22}{30}\selectfont
  \begin{itemize}[itemsep=4pt]
    \item AWS 46\% $\downarrow$ from 51\% --- Azure gaining
    \item \textbf{Docker:} 49\% use containers locally
  \end{itemize}
}

% ════════════════════════════════════════════════
% AI INTEGRATION (right column)
% ════════════════════════════════════════════════
\posterbox[
  bluecard, title={AI in the Developer Workflow}
]{name=ai, column=2, between=row15 and row18}{
  \posterfig{0.95}{figures/ai_integration.png}{18\% of developers now build AI integrations. Python dominates at 31\% AI involvement.}

  \fontsize{22}{30}\selectfont
  \begin{itemize}[itemsep=4pt]
    \item \textbf{\color{primary}18\%} of devs build AI integrations
    \item 31\% of Python devs in AI/ML work
    \item 11\% of C++ devs in AI --- surprising
    \item AI fear diminishing year over year
  \end{itemize}
}

% ════════════════════════════════════════════════
% KEY TAKEAWAYS (bottom banner)
% ════════════════════════════════════════════════
\posterbox[
  highlightcard, title={Key Takeaways}
]{name=takeaways, column=1, span=2, between=row18 and row20}{
  \fontsize{24}{32}\selectfont
  \centering
  \begin{minipage}[c]{0.31\linewidth}
    \colorbox{primary!25!bgposter}{\parbox{0.92\linewidth}{%
      \centering\vspace{4pt}%
      \textbf{\color{primary}The language hierarchy is reshaping}\\
      Python closes in on JavaScript; the 4pt gap is historic%
      \vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}
    \colorbox{secondary!25!bgposter}{\parbox{0.92\linewidth}{%
      \centering\vspace{4pt}%
      \textbf{\color{secondary}TypeScript is the breakout story}\\
      Promise Index \#1 at 199 --- where the ecosystem is heading%
      \vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}
    \colorbox{accent!25!bgposter}{\parbox{0.92\linewidth}{%
      \centering\vspace{4pt}%
      \textbf{\color{accent}AI is entering production workflows}\\
      18\% of devs building integrations; Python leads AI/ML%
      \vspace{4pt}%
    }}
  \end{minipage}
}

\end{tcbposter}
\end{document}

